@classmethod
def eval(cls, arg, base=None):
    from sympy.calculus import AccumBounds
    from sympy.sets.setexpr import SetExpr

    arg = sympify(arg)

    if base is not None:
        base = sympify(base)
        if base == 1:
            if arg == 1:
                return S.NaN
            else:
                return S.ComplexInfinity
        try:
            # handle extraction of powers of the base now
            # or else expand_log in Mul would have to handle this
            n = multiplicity(base, arg)
            if n:
                return n + log(arg / base**n) / log(base)
            else:
                return log(arg)/log(base)
        except ValueError:
            pass
        if base is not S.Exp1:
            return cls(arg)/cls(base)
        else:
            return cls(arg)

    if arg.is_Number:
        if arg.is_zero:
            return S.ComplexInfinity
        elif arg is S.One:
            return S.Zero
        elif arg is S.Infinity:
            return S.Infinity
        elif arg is S.NegativeInfinity:
            return S.Infinity
        elif arg is S.NaN:
            return S.NaN
        elif arg.is_Rational and arg.p == 1:
            return -cls(arg.q)

    if arg.is_Pow and arg.base is S.Exp1 and arg.exp.is_extended_real:
        return arg.exp
    if isinstance(arg, exp) and arg.exp.is_extended_real:
        return arg.exp
    elif isinstance(arg, exp) and arg.exp.is_number:
        r_, i_ = match_real_imag(arg.exp)
        if i_ and i_.is_comparable:
            i_ %= 2*pi
            if i_ > pi:
                i_ -= 2*pi
            return r_ + expand_mul(i_ * I, deep=False)
    elif isinstance(arg, exp_polar):
        return unpolarify(arg.exp)
    elif isinstance(arg, AccumBounds):
        if arg.min.is_positive:
            return AccumBounds(log(arg.min), log(arg.max))
        elif arg.min.is_zero:
            return AccumBounds(S.NegativeInfinity, log(arg.max))
        else:
            return S.NaN
    elif isinstance(arg, SetExpr):
        return arg._eval_func(cls)

    if arg.is_number:
        if arg.is_negative:
            return pi * I + cls(-arg)
        elif arg is S.ComplexInfinity:
            return S.ComplexInfinity
        elif arg is S.Exp1:
            return S.One

    if arg.is_zero:
        return S.ComplexInfinity

    # don't autoexpand Pow or Mul (see the issue 3351):
    if not arg.is_Add:
        coeff = arg.as_coefficient(I)

        if coeff is not None:
            if coeff is S.Infinity:
                return S.Infinity
            elif coeff is S.NegativeInfinity:
                return S.Infinity
            elif coeff.is_Rational:
                if coeff.is_nonnegative:
                    return pi * I * S.Half + cls(coeff)
                else:
                    return -pi * I * S.Half + cls(-coeff)

    if arg.is_number and arg.is_algebraic:
        # Match arg = coeff*(r_ + i_*I) with coeff>0, r_ and i_ real.
        coeff, arg_ = arg.as_independent(I, as_Add=False)
        if coeff.is_negative:
            coeff *= -1
            arg_ *= -1
        arg_ = expand_mul(arg_, deep=False)
        r_, i_ = arg_.as_independent(I, as_Add=True)
        i_ = i_.as_coefficient(I)
        if coeff.is_real and i_ and i_.is_real and r_.is_real:
            if r_.is_zero:
                if i_.is_positive:
                    return pi * I * S.Half + cls(coeff * i_)
                elif i_.is_negative:
                    return -pi * I * S.Half + cls(coeff * -i_)
            else:
                from sympy.simplify import ratsimp
                # Check for arguments involving rational multiples of pi
                t = (i_/r_).cancel()
                t1 = (-t).cancel()
                atan_table = _log_atan_table()
                if t in atan_table:
                    modulus = ratsimp(coeff * Abs(arg_))
                    if r_.is_positive:
                        return cls(modulus) + I * atan_table[t]
                    else:
                        return cls(modulus) + I * (atan_table[t] - pi)
                elif t1 in atan_table:
                    modulus = ratsimp(coeff * Abs(arg_))
                    if r_.is_positive:
                        return cls(modulus) + I * (-atan_table[t1])
                    else:
                        return cls(modulus) + I * (pi - atan_table[t1])

@staticmethod
@cacheit
def taylor_term(n, x, *previous_terms):  # of log(1+x)
    r"""
    Returns the next term in the Taylor series expansion of `\log(1+x)`.
    """
    from sympy.simplify.powsimp import powsimp
    if n < 0:
        return S.Zero
    x = sympify(x)
    if n == 0:
        return x
    if previous_terms:
        p = previous_terms[-1]
        if p is not None:
            return powsimp((-n) * p * x / (n + 1), deep=True, combine='exp')
    return (1 - 2*(n % 2)) * x**(n + 1)/(n + 1)

def _eval_expand_log(self, deep=True, **hints):
        from sympy.concrete import Sum, Product
        force = hints.get('force', False)
        factor = hints.get('factor', False)
        if (len(self.args) == 2):
            return expand_log(self.func(*self.args), deep=deep, force=force)
        arg = self.args[0]
        if arg.is_Integer:
            # remove perfect powers
            p = perfect_power(arg)
            logarg = None
            coeff = 1
            if p is not False:
                arg, coeff = p
                logarg = self.func(arg)
            # expand as product of its prime factors if factor=True
            if factor:
                p = factorint(arg)
                if arg not in p.keys():
                    logarg = sum(n*log(val) for val, n in p.items())
            if logarg is not None:
                return coeff*logarg
        elif arg.is_Rational:
            return log(arg.p) - log(arg.q)
        elif arg.is_Mul:
            expr = []
            nonpos = []
            for x in arg.args:
                if force or x.is_positive or x.is_polar:
                    a = self.func(x)
                    if isinstance(a, log):
                        expr.append(self.func(x)._eval_expand_log(**hints))
                    else:
                        expr.append(a)
                elif x.is_negative:
                    a = self.func(-x)
                    expr.append(a)
                    nonpos.append(S.NegativeOne)
                else:
                    nonpos.append(x)
            return Add(*expr) + log(Mul(*nonpos))
        elif arg.is_Pow or isinstance(arg, exp):
            if force or (arg.exp.is_extended_real and (arg.base.is_positive or ((arg.exp+1)
                .is_positive and (arg.exp-1).is_nonpositive))) or arg.base.is_polar:
                b = arg.base
                e = arg.exp
                a = self.func(b)
                if isinstance(a, log):
                    return unpolarify(e) * a._eval_expand_log(**hints)
                else:
                    return unpolarify(e) * a
        elif isinstance(arg, Product):
            if force or arg.function.is_positive:
                return Sum(log(arg.function), *arg.limits)

        return self.func(arg)

def _eval_simplify(self, **kwargs):
        from sympy.simplify.simplify import expand_log, simplify, inversecombine
        if len(self.args) == 2:  # it's unevaluated
            return simplify(self.func(*self.args), **kwargs)

        expr = self.func(simplify(self.args[0], **kwargs))
        if kwargs['inverse']:
            expr = inversecombine(expr)
        expr = expand_log(expr, deep=True)
        return min([expr, self], key=kwargs['measure'])

def _eval_is_rational(self):
        s = self.func(*self.args)
        if s.func == self.func:
            if (self.args[0] - 1).is_zero:
                return True
            if s.args[0].is_rational and fuzzy_not((self.args[0] - 1).is_zero):
                return False
        else:
            return s.is_rational

def _eval_is_algebraic(self):
        s = self.func(*self.args)
        if s.func == self.func:
            if (self.args[0] - 1).is_zero:
                return True
            elif fuzzy_not((self.args[0] - 1).is_zero):
                if self.args[0].is_algebraic:
                    return False
        else:
            return s.is_algebraic

def _eval_is_complex(self):
        z = self.args[0]
        return fuzzy_and([z.is_complex, fuzzy_not(z.is_zero)])

def _eval_is_finite(self):
        arg = self.args[0]
        if arg.is_zero:
            return False
        return arg.is_finite

def _eval_nseries(self, x, n, logx, cdir=0):
        # NOTE Please see the comment at the beginning of this file, labelled
        #      IMPORTANT.
        from sympy.series.order import Order
        from sympy.simplify.simplify import logcombine
        from sympy.core.symbol import Dummy

        if self.args[0] == x:
            return log(x) if logx is None else logx
        arg = self.args[0]
        t = Dummy('t', positive=True)
        if cdir == 0:
            cdir = 1
        z = arg.subs(x, cdir*t)

        k, l = Wild("k"), Wild("l")
        r = z.match(k*t**l)
        if r is not None:
            k, l = r[k], r[l]
            if l != 0 and not l.has(t) and not k.has(t):
                r = l*log(x) if logx is None else l*logx
                r += log(k) - l*log(cdir) # XXX true regardless of assumptions?
