        # Min(Max(x, y, z), Max(x, y, u, v)) -> {x,y}, ({z}, {u,v})
        arg_sets = [set(arg.args) for arg in other_args]
        common = set.intersection(*arg_sets)
        if not common:
            return args

        new_other_args = list(common)
        arg_sets_diff = [arg_set - common for arg_set in arg_sets]

        # If any set is empty after removing common then all can be
        # discarded e.g. Min(Max(a, b, c), Max(a, b)) -> Max(a, b)
        if all(arg_sets_diff):
            other_args_diff = [other(*s, evaluate=False) for s in arg_sets_diff]
            new_other_args.append(cls(*other_args_diff, evaluate=False))

        other_args_factored = other(*new_other_args, evaluate=False)
        return remaining_args + [other_args_factored]

    if len(args) > 1:
        args = factor_minmax(args)

    return args

def do(ai, a):
            if not isinstance(ai, (Min, Max)):
                return ai
            cond = a in ai.args
            if not cond:
                return ai.func(*[do(i, a) for i in ai.args],
                    evaluate=False)
            if isinstance(ai, cls):
                return ai.func(*[do(i, a) for i in ai.args if i != a],
                    evaluate=False)
            return a

@classmethod
def _new_args_filter(cls, arg_sequence):
    """
    Generator filtering args.

    first standard filter, for cls.zero and cls.identity.
    Also reshape ``Max(a, Max(b, c))`` to ``Max(a, b, c)``,
    and check arguments for comparability
    """
    for arg in arg_sequence:
        # pre-filter, checking comparability of arguments
        if not isinstance(arg, Expr) or arg.is_extended_real is False or (
                arg.is_number and
                not arg.is_comparable):
            raise ValueError("The argument '%s' is not comparable." % arg)

        if arg == cls.zero:
            raise ShortCircuit(arg)
        elif arg == cls.identity:
            continue
        elif arg.func == cls:
            yield from arg.args
        else:
            yield arg

@classmethod
def _find_localzeros(cls, values, **options):
    """
    Sequentially allocate values to localzeros.

    When a value is identified as being more extreme than another member it
    replaces that member; if this is never true, then the value is simply
    appended to the localzeros.
    """
    localzeros = set()
    for v in values:
        is_newzero = True
        localzeros_ = list(localzeros)
        for z in localzeros_:
            if id(v) == id(z):
                is_newzero = False
            else:
                con = cls._is_connected(v, z)
                if con:
                    is_newzero = False
                    if con is True or con == cls:
                        localzeros.remove(z)
                        localzeros.update([v])
        if is_newzero:
            localzeros.update([v])
    return localzeros

@classmethod
def _is_connected(cls, x, y):
    """
    Check if x and y are connected somehow.
    """
    for i in range(2):
        if x == y:
            return True
        t, f = Max, Min
        for op in "><":
            for j in range(2):
                try:
                    if op == ">":
                        v = x >= y
                    else:
                        v = x <= y
                except TypeError:
                    return False  # non-real arg
                if not v.is_Relational:
                    return t if v else f
                t, f = f, t
                x, y = y, x
            x, y = y, x  # run next pass with reversed order relative to start
        # simplification can be expensive, so be conservative
        # in what is attempted
        x = factor_terms(x - y)
        y = S.Zero

    return False

def _eval_derivative(self, s):
        # f(x).diff(s) -> x.diff(s) * f.fdiff(1)(s)
        i = 0
        l = []
        for a in self.args:
            i += 1
            da = a.diff(s)
            if da.is_zero:
                continue
            try:
                df = self.fdiff(i)
            except ArgumentIndexError:
                df = super().fdiff(i)
            l.append(df * da)
        return Add(*l)

def _eval_rewrite_as_Abs(self, *args, **kwargs):
        from sympy.functions.elementary.complexes import Abs
        s = (args[0] + self.func(*args[1:]))/2
        d = abs(args[0] - self.func(*args[1:]))/2
        return (s + d if isinstance(self, Max) else s - d).rewrite(Abs)

def fdiff( self, argindex ):
        from sympy.functions.special.delta_functions import Heaviside
        n = len(self.args)
        if 0 < argindex and argindex <= n:
            argindex -= 1
            if n == 2:
                return Heaviside(self.args[argindex] - self.args[1 - argindex])
            newargs = tuple([self.args[i] for i in range(n) if i != argindex])
            return Heaviside(self.args[argindex] - Max(*newargs))
        else:
            raise ArgumentIndexError(self, argindex)

def _eval_rewrite_as_Heaviside(self, *args, **kwargs):
        from sympy.functions.special.delta_functions import Heaviside
        return Add(*[j*Mul(*[Heaviside(j - i) for i in args if i!=j]) \
                for j in args])

class Min(MinMaxBase, Application):
    """
    Return, if possible, the minimum value of the list.
    It is named ``Min`` and not ``min`` to avoid conflicts
    with the built-in function ``min``.

    Examples
    ========

    >>> from sympy import Min, Symbol, oo
    >>> from sympy.abc import x, y
    >>> p = Symbol('p', positive=True)
    >>> n = Symbol('n', negative=True)

    >>> Min(x, -2)
    Min(-2, x)
    >>> Min(x, -2).subs(x, 3)
    -2
    >>> Min(p, -3)
    -3
    >>> Min(x, y)
    Min(x, y)
    >>> Min(n, 8, p, -7, p, oo)
    Min(-7, n)

    See Also
    ========

    Max : find maximum values
    """
    zero = S.NegativeInfinity
    identity = S.Infinity

    def fdiff( self, argindex ):
        from sympy.functions.special.delta_functions import Heaviside
        n = len(self.args)
        if 0 < argindex and argindex <= n:
            argindex -= 1
            if n == 2:
                return Heaviside( self.args[1-argindex] - self.args[argindex] )
            newargs = tuple([ self.args[i] for i in range(n) if i != argindex])
            return Heaviside( Min(*newargs) - self.args[argindex] )
        else:
            raise ArgumentIndexError(self, argindex)

    def _eval_rewrite_as_Heaviside(self, *args, **kwargs):
        from sympy.functions.special.delta_functions import Heaviside
        return Add(*[j*Mul(*[Heaviside(i-j) for i in args if i!=j]) \
                for j in args])

    def _eval_rewrite_as_Piecewise(self, *args, **kwargs):
        return _minmax_as_Piecewise('<=', *args)

    def _eval_is_positive(self):
        return fuzzy_and(a.is_positive for a in self.args)

    def _eval_is_nonnegative(self):
        return fuzzy_and(a.is_nonnegative for a in self.args)

    def _eval_is_negative(self):
        return fuzzy_or(a.is_negative for a in self.args)

def fdiff( self, argindex ):
        from sympy.functions.special.delta_functions import Heaviside
        n = len(self.args)
        if 0 < argindex and argindex <= n:
            argindex -= 1
            if n == 2:
                return Heaviside( self.args[1-argindex] - self.args[argindex] )
            newargs = tuple([ self.args[i] for i in range(n) if i != argindex])
            return Heaviside( Min(*newargs) - self.args[argindex] )
        else:
            raise ArgumentIndexError(self, argindex)

def _eval_rewrite_as_Heaviside(self, *args, **kwargs):
